# =================================================================
# MAPA EXCLUSIVO DE TEXTOS (leyendas)
# ARCHIVO GENERADO AUTOMÁTICAMENTE A PARTIR DE LA DEFINICIÓN: layers.03_rezago_educativo.02_rezago_localidad_rural 
# DESCRIPCIÓN: Localidades rurales con rezago educativo Censo 2020 
# =================================================================

LAYER
  NAME "t_analfabetas"
  STATUS ON
  TYPE POINT
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, analfabetas, nomgeo FROM rezago_educativo_censo_2020.rez_loc_rur) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Texto Número de personas en Rezago Educativo por localidad rural"
    "wms_enable_request" "*"
  END
  LABELITEM "nomgeo"
  CLASS
    LABEL
      FONT "arial"
      SIZE 8
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      PRIORITY 1
      BUFFER 1
      POSITION uc
      TYPE truetype
      WRAP " "
      MAXLENGTH 10
      ALIGN center
    END
    SYMBOL "circulor"
    SIZE 10
    OUTLINECOLOR 0 0 0
    COLOR 42 212 48
  END
END

